SET lock_timeout = '5s';
-- FIN-017: specialty starter price lists for the setup wizard. Platform reference data maintained by Nabd: no tenant_id,
-- SELECT-only for the API role, changes ship as migrations (bump version). heads is the ordered list the wizard pre-fills:
-- [{ code, name, category, baseAmount, taxCategory, taxRatePercent, sacHsn, displayOrder }].
-- Amounts are suggestions the owner sees and edits before anything is saved. Tax categories and rates reuse what billing
-- already has: India exempt health care (SAC 9993xx) and the 18% slab for cosmetic and aesthetic services (FIN-009 seed),
-- KSA VAT 15% and UAE VAT 5% (regions.standard_tax_rate), UAE healthcare zero_rated. None of it is reviewed yet:
-- reviewed = false until the billing SME and a chartered accountant sign it off (open decision 64).
CREATE TABLE price_templates (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  specialty    text NOT NULL CHECK (specialty IN ('dental', 'derma', 'gp', 'paediatric', 'physio', 'other')),
  jurisdiction text NOT NULL CHECK (jurisdiction IN ('IN', 'SA', 'AE')),
  heads        jsonb NOT NULL CHECK (jsonb_typeof(heads) = 'array'),
  version      int NOT NULL DEFAULT 1,
  reviewed     boolean NOT NULL DEFAULT false,
  review_note  text NOT NULL,
  updated_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (specialty, jurisdiction)
);
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'nabd_app') THEN
    REVOKE ALL ON price_templates FROM nabd_app;
    GRANT SELECT ON price_templates TO nabd_app;
  END IF;
END $$;

